WITH "m0" AS ( UPDATE "public"."mutation_item" AS "s" SET "score" = $1 WHERE ( true AND ( "s"."id" = $2 ) ) RETURNING "s" AS "t0" , NULL::tid AS "k0" ), "r0" AS (SELECT ( "t0" ).* FROM "m0" ) SELECT (SELECT row_to_json((SELECT "%" FROM (SELECT "t0"."id" AS "id" , "t0"."score" AS "score" , "t0"."note" AS "note" , "c3"."j" AS "owner" ) AS "%")) FROM "r0" AS "t0" LEFT JOIN LATERAL (SELECT row_to_json((SELECT "%" FROM (SELECT "t1"."id" AS "id" ) AS "%")) AS "j" FROM ( SELECT "s".* FROM "public"."mutation_author" AS "s" WHERE true AND "s"."id" = "t0"."owner_id" AND ( ( true ) ) LIMIT 1 ) AS "t1" ) AS "c3" ON true )
